# Lecturas narrativas: vinculan la decision con la evidencia que puede sostener.
# Complementan, sin eliminar, ejemplos, formulas y reservas de los cuadernos anteriores.
study_catalog <- function() list(
  load = list(reading = "Imagina que abres una exportaci\u00f3n de Web of Science y ves Abstract junto a Article Title. Para estudiar el contenido de los art\u00edculos, el punto de partida habitual es Abstract. Abre el visor: si puedes leer un resumen completo, el texto se ha reconocido; si solo ves t\u00edtulos, cambia la correspondencia en Preparaci\u00f3n. La importaci\u00f3n puede ser v\u00e1lida aunque algunas filas carezcan de resumen. Esas ausencias deben verse en la cobertura, no rellenarse con texto inventado.",
    reporting = "En el m\u00e9todo puedes escribir: \u00abSe import\u00f3 la hoja [nombre] del archivo exportado de [base], con [n] registros. Se analiz\u00f3 la columna [texto] y se verificaron la correspondencia de metadatos y las ausencias\u00bb. Completa la b\u00fasqueda y la fecha de extracci\u00f3n: el nombre del archivo no permite reconstruirlas."),
  prepare = list(reading = "Piensa en preparar como construir la versi\u00f3n del corpus que responde a tu pregunta. Si excluyes registros de otros a\u00f1os, cambia el conjunto de documentos. Si eliminas una palabra vac\u00eda, cambian sus representaciones textuales. Por eso conviene revisar por separado la auditor\u00eda de documentos y los t\u00e9rminos excluidos. Un resumen que quede sin palabras \u00fatiles sigue siendo un documento del corpus, pero algunos modelos no podr\u00e1n representarlo.",
    reporting = "Describe los filtros y sus efectos: \u00abDe [n] registros importados se conservaron [m] tras [criterios]; la normalizaci\u00f3n utiliz\u00f3 [reglas], y [e] documentos no aportaron vocabulario al modelo\u00bb. Guarda la entrega antes de cambiar decisiones para poder comparar ejecuciones."),
  lemma = list(reading = "Si estudiantes, estudiante y estudiando aparecen como formas distintas, la lematizaci\u00f3n puede reunir las flexiones que el modelo reconoce. As\u00ed reduces dispersi\u00f3n sin tratar como equivalentes todos los conceptos relacionados. Lee algunos originales junto a sus lemas: una sigla o un t\u00e9rmino t\u00e9cnico mal analizado puede justificar conservar las formas originales. Para un corpus mixto, la decisi\u00f3n inicial es Varios idiomas; CLD2 estima cada resumen y deja visibles los casos que requieren revisi\u00f3n.",
    reporting = "Documenta qu\u00e9 idiomas se aplicaron, c\u00f3mo resolviste los pendientes y qu\u00e9 modelos se utilizaron. \u00abSe lematiz\u00f3 por documento con UDPipe; las asignaciones autom\u00e1ticas se revisaron mediante [procedimiento]\u00bb. No escribas que el corpus se tradujo o que sus lenguas se fusionaron: los lemas siguen perteneciendo a idiomas diferentes."),
  tokens = list(reading = "Antes de elegir un filtro, preg\u00fantate qu\u00e9 informaci\u00f3n quieres conservar. Si hospital aparece muchas veces en una sola revisi\u00f3n, su frecuencia ser\u00e1 alta, pero su presencia documental seguir\u00e1 siendo uno. Si aparece una vez en casi todos los art\u00edculos, su presencia ser\u00e1 alta aunque no distinga unos textos de otros. TF-IDF combina ocupaci\u00f3n dentro del texto y rareza entre textos; permite localizar vocabulario distintivo, pero una errata tambi\u00e9n puede ser rara. El indicador orienta una revisi\u00f3n, no decide por ti qu\u00e9 es cient\u00edficamente importante.",
    reporting = "Justifica cada umbral por su efecto observado. Puedes escribir: \u00abSe exigi\u00f3 presencia en al menos [n] documentos y se revisaron los t\u00e9rminos excluidos para evitar eliminar vocabulario relevante\u00bb. Si filtras por TF-IDF o entrop\u00eda, informa la f\u00f3rmula, la unidad textual y el umbral; evita afirmar que se eliminaron todas las palabras irrelevantes."),
  explore = list(reading = "Un ranking es una puerta de entrada a los documentos. Si una autora encabeza la lista, abre sus registros y comprueba variantes del nombre y coautor\u00edas. Si suben las citas medias, mira cu\u00e1ntos documentos tienen ese dato y cu\u00e1ndo se extrajo: a\u00f1os antiguos han tenido m\u00e1s tiempo para recibir citas. Antes de hablar de una tendencia del campo, distingue lo observado en esta b\u00fasqueda de lo que podr\u00eda ocurrir fuera de ella.",
    reporting = "Una formulaci\u00f3n verificable es: \u00abEn el corpus recuperado, [fuente] re\u00fane [n] documentos de [total con fuente]\u00bb. A\u00f1ade cobertura y criterio de conteo. Sustituir esa frase por \u00abla revista m\u00e1s importante\u00bb introducir\u00eda una valoraci\u00f3n que el ranking no ha medido."),
  models = list(reading = "La pregunta gu\u00eda la elecci\u00f3n. Para ver c\u00f3mo un resumen mezcla patrones de vocabulario, consulta LDA. Para explorar agrupaciones, revisa UMAP/HDBSCAN y los documentos sin asignar. Para resumir diferencias de perfiles, consulta ACP o correspondencias. La tabla de comparaci\u00f3n conserva estas diferencias: que dos m\u00e9todos coincidan puede apoyar una lectura, pero que discrepen requiere estudiar representaciones, cobertura y supuestos.",
    reporting = "Explica para qu\u00e9 utilizaste cada modelo y c\u00f3mo validaste su lectura con documentos. Un m\u00e9todo adicional debe aportar evidencia a la pregunta; no aumenta por s\u00ed solo el rigor. Conserva par\u00e1metros y versiones junto a la ejecuci\u00f3n presentada."),
  lda = list(reading = "Empieza por un tema y lee sus palabras con mayor beta. Despu\u00e9s abre varios documentos con proporci\u00f3n alta y alguno que mezcle temas. Solo entonces propone una etiqueta. Si hospital y prevenci\u00f3n aparecen junto a escuelas, el nombre Salud puede resultar demasiado amplio o esconder un v\u00ednculo educativo. La composici\u00f3n de un documento y la prevalencia media de un tema responden a escalas distintas: una barra individual no representa el porcentaje de art\u00edculos del corpus.",
    reporting = "Puedes informar: \u00abEl Tema [k], provisionalmente denominado [etiqueta], se interpret\u00f3 a partir de [t\u00e9rminos] y de los documentos [ID]\u00bb. Explica casos ambiguos y sensibilidad al n\u00famero de temas. La etiqueta es una interpretaci\u00f3n del investigador, no una categor\u00eda conocida por LDA."),
  ca = list(reading = "Antes de dar significado a una esquina del plano, mira cu\u00e1nta inercia recogen sus dos ejes. Despu\u00e9s consulta el cos\u00b2 de las palabras que quieres interpretar. Una palabra bien representada ofrece una lectura m\u00e1s fiel en ese plano; una con cos\u00b2 bajo necesita otros ejes. Las contribuciones ayudan a nombrar el contraste: el eje se interpreta con los t\u00e9rminos que lo construyen y con sus documentos, no por el signo positivo o negativo en s\u00ed mismo.",
    reporting = "Una lectura prudente ser\u00eda: \u00abEl plano recoge [p]% de la inercia; el primer eje contrapone perfiles caracterizados por [t\u00e9rminos], cuya representaci\u00f3n se comprob\u00f3 mediante cos\u00b2\u00bb. No describas como cl\u00fasteres confirmados los conjuntos que parecen pr\u00f3ximos en una proyecci\u00f3n."),
  density = list(reading = "Usa la primera ejecuci\u00f3n como hip\u00f3tesis de trabajo. Lee los textos de cada grupo y los casos con baja membres\u00eda; revisa tambi\u00e9n los que quedaron sin asignar. Despu\u00e9s cambia un par\u00e1metro cada vez. Si ampliar vecinos fusiona dos grupos, comprueba si la separaci\u00f3n anterior respond\u00eda a vocabulario superficial o a contenidos distintos. min_dist controla compactaci\u00f3n de UMAP; no es un umbral de distancia de HDBSCAN. Un mapa compacto puede seguir agrupando mal documentos para tu pregunta.",
    reporting = "Informa la representaci\u00f3n, vecinos, dimensiones, min_dist, minPts, semilla y proporci\u00f3n sin asignar. Describe c\u00f3mo comprobaste los grupos con documentos. La ruta l\u00e9xica permite un flujo inspirado en BERTopic, pero no debe presentarse como un an\u00e1lisis con BERT si no se importaron vectores de ese origen."),
  networks = list(reading = "Una l\u00ednea solo tiene sentido si sabemos qu\u00e9 la gener\u00f3. En coautor\u00eda significa una firma compartida; en cocitaci\u00f3n, dos referencias citadas por el mismo documento. En fuentes, aqu\u00ed representa afinidad l\u00e9xica. Lee esa definici\u00f3n antes de comparar tama\u00f1os y comunidades. Si dos nodos parecen cercanos al arrastrarlos, solo ha cambiado el dibujo. El resumen de m\u00e9tricas y las conexiones reales permiten comprobar las conclusiones que la imagen sugiere.",
    reporting = "Describe los nodos, la relaci\u00f3n, el conteo y los filtros: \u00abSe construy\u00f3 una red de [entidades] conectadas por [regla], con pesos [definici\u00f3n]\u00bb. Informa cobertura y umbral. Una centralidad alta describe una posici\u00f3n en esta red; atribuir liderazgo o prestigio exige evidencia adicional."),
  jsd = list(reading = "El gr\u00e1fico de shifts explica de d\u00f3nde sale la diferencia global. Una barra hacia B identifica un t\u00e9rmino con mayor proporci\u00f3n en B; hacia A, uno con mayor proporci\u00f3n en A. Su longitud muestra cu\u00e1nto aporta a la JSD, expresado como porcentaje de la divergencia total. La direcci\u00f3n y la aportaci\u00f3n son preguntas diferentes: una palabra puede aumentar y explicar poco del contraste si otras diferencias son mucho mayores. Lee la cobertura de las barras mostradas para saber cu\u00e1nto del resultado has examinado.",
    reporting = "Una redacci\u00f3n adaptable es: \u00abSe compararon los perfiles l\u00e9xicos de [A] y [B] mediante JSD en bits, con mezcla 50/50 y ponderaci\u00f3n [elegida]. Los t\u00e9rminos mostrados explicaron [p]% de la divergencia. Se contrastaron sus contextos antes de interpretar el cambio\u00bb. JSD positiva no demuestra una evoluci\u00f3n conceptual ni su causa."),
  pca = list(reading = "El perfil TF-IDF permite comparar documentos como filas de n\u00fameros. ACP resume c\u00f3mo var\u00edan esas filas. Mira primero la varianza de los ejes y despu\u00e9s la representaci\u00f3n de cada punto: dos documentos pr\u00f3ximos en el plano pueden diferir en la parte que no se dibuja. Para entender una direcci\u00f3n, consulta los t\u00e9rminos asociados al componente y vuelve a los res\u00famenes. Si estandarizas, comprueba qu\u00e9 t\u00e9rminos de poca variaci\u00f3n adquieren peso y si esa decisi\u00f3n responde a tu pregunta.",
    reporting = "Puedes indicar: \u00abSe aplic\u00f3 ACP a perfiles TF-IDF centrados [con/sin estandarizaci\u00f3n]; el plano explic\u00f3 [p]% de la varianza\u00bb. A\u00f1ade vocabulario, exclusiones y calidad de representaci\u00f3n de los objetos interpretados. ACP por s\u00ed solo no ha identificado clases tem\u00e1ticas."),
  export = list(reading = "Abre primero el informe y comprueba una cifra contra su CSV completo. Despu\u00e9s verifica que la entrega incluye par\u00e1metros, datos exactos y c\u00f3digo. El informe organiza evidencia; la explicaci\u00f3n cient\u00edfica exige relacionarla con tu pregunta, literatura y l\u00edmites. Si utilizas una skill o un prompt, empieza por una tabla de afirmaciones verificables y revisa el borrador frase por frase. La fluidez del texto no sustituye ese trabajo.",
    reporting = "La declaraci\u00f3n de asistencia debe describir lo que realmente hiciste y ajustarse a tu instituci\u00f3n y revista. Los autores humanos conservan la autor\u00eda, deciden el argumento y supervisan exhaustivamente datos, referencias e interpretaci\u00f3n. No atribuyas a una herramienta validaciones que no realizaste."),
  bm25 = list(reading = "BM25 aumenta el peso al repetir un t\u00e9rmino, pero cada repetici\u00f3n adicional aporta menos. Tambi\u00e9n ajusta por longitud: encontrar cinco menciones en un resumen corto no recibe el mismo tratamiento que en uno muy largo. El par\u00e1metro de repeticiones (k1) regula cu\u00e1nto sigue aportando repetir una palabra. El par\u00e1metro de longitud (b) regula cu\u00e1nto se ajusta por las palabras del texto. Son decisiones de representaci\u00f3n; en esta app no convierten el peso en una prueba de relevancia ni sustituyen los conteos que necesita LDA.",
    reporting = "Compara TF-IDF y BM25 manteniendo documentos y dem\u00e1s decisiones. Lee qu\u00e9 t\u00e9rminos y grupos cambian. Documenta k1 y b si utilizas BM25; su fama en recuperaci\u00f3n de informaci\u00f3n no demuestra que sea la mejor ponderaci\u00f3n para este corpus."),
  seed = list(reading = "La semilla permite empezar de la misma secuencia aleatoria. Si dos ejecuciones con la misma semilla difieren, comprueba tambi\u00e9n versiones y decisiones. Si distintas semillas producen grupos parecidos, has observado una se\u00f1al de estabilidad en esas pruebas. Rotar o reflejar el mapa puede cambiar su apariencia sin cambiar asignaciones: revisa los documentos, no solo las coordenadas.",
    reporting = "Separa reproducibilidad y sensibilidad: registra la semilla de la figura publicada y explica qu\u00e9 ejecuciones alternativas contrastaste. HDBSCAN es determinista con las mismas coordenadas; esas coordenadas pueden cambiar por el componente aleatorio de UMAP."),
  ngrams = list(reading = "Imagina diez menciones de atenci\u00f3n primaria en una revisi\u00f3n y una menci\u00f3n en cada uno de diez art\u00edculos. La frecuencia empata, pero presencia y concentraci\u00f3n cuentan historias distintas. TF-IDF responde cu\u00e1nto ocupa la expresi\u00f3n en un documento y cu\u00e1nto lo distingue. Si buscas una l\u00ednea extendida, empieza por presencia; si buscas vocabulario particular de algunos textos, revisa TF-IDF junto a sus contextos. Un ranking de expresiones no demuestra por s\u00ed solo asociaci\u00f3n estad\u00edstica entre sus palabras.",
    reporting = "Especifica longitud del n-grama, normalizaci\u00f3n, fronteras y criterio de ordenaci\u00f3n. Si informas TF-IDF medio, recuerda que su denominador utiliza documentos que aportan expresiones v\u00e1lidas de esa longitud; la cobertura documental se refiere al corpus preparado."),
  roles = list(reading = "Un nodo con mucho grado tiene muchos vecinos; uno con alta fuerza acumula m\u00e1s peso. Un puente entre comunidades puede tener pocos vecinos y mucha intermediaci\u00f3n. Son papeles estructurales diferentes. Los candidatos de cobertura conjunta ayudan a escoger nodos que alcanzan vecinos nuevos; esa heur\u00edstica no identifica autom\u00e1ticamente personas influyentes. Lee las conexiones que justifican el papel y revisa variantes de nombres antes de interpretarlo.",
    reporting = "Usa t\u00e9rminos verificables: \u00abEl nodo [ID] conecta [n] vecinos y presenta [m\u00e9trica] en la red analizada\u00bb. Explica ponderaci\u00f3n y universo. Si lo llamas puente, muestra qu\u00e9 partes conecta; si lo llamas l\u00edder, necesitar\u00e1s evidencia que esta m\u00e9trica no ofrece."),
  references = list(reading = "Empieza comprobando si tienes referencias citadas o solo un n\u00famero de citas recibidas. El Excel de ejemplo tiene una columna Cited References vac\u00eda: su existencia no aporta bibliograf\u00edas. Podr\u00e1s describir los conteos de citas registrados, pero no reconstruir redes de referencias con esa columna. Si tu pregunta necesita cocitaci\u00f3n o acoplamiento, exporta las referencias y revisa su formato antes de continuar.",
    reporting = "Informa cu\u00e1ntos documentos aportan bibliograf\u00eda, c\u00f3mo separaste las referencias y c\u00f3mo trataste variantes. El matching de esta app normaliza cadenas, pero no resuelve todas las identidades bibliogr\u00e1ficas. Un ranking de referencias internas no equivale al total de citas que esas obras recibieron en la base."),
  coverage = list(reading = "La ausencia de un dato limita una pregunta concreta. Cien documentos con t\u00edtulo pueden permitir lectura, pero si solo treinta tienen a\u00f1o, la evoluci\u00f3n temporal utilizar\u00e1 esos treinta. Observa si los faltantes se concentran en una fuente o periodo: en ese caso la parte conocida puede tener una composici\u00f3n distinta. La tabla de cobertura ayuda a decidir si basta declarar la limitaci\u00f3n o necesitas mejorar la exportaci\u00f3n.",
    reporting = "Acompa\u00f1a cada resultado con su base disponible: \u00abLa evoluci\u00f3n se calcul\u00f3 sobre [n] registros con a\u00f1o v\u00e1lido de [total]\u00bb. Un dato ausente no se interpreta como cero y una cobertura alta no garantiza que la b\u00fasqueda sea representativa del campo."),
  bradford = list(reading = "Dos preguntas distintas. La curva de Cobertura y referencias responde cu\u00e1ntas fuentes necesitas para reunir una proporci\u00f3n del corpus. La pesta\u00f1a Leyes bibliom\u00e9tricas a\u00f1ade las tres zonas de Bradford y compara cu\u00e1ntas revistas necesita cada zona. Si los multiplicadores son parecidos, el reparto se acerca al esquema de Bradford; eso describe tu b\u00fasqueda y no prueba la ley.",
    reporting = "Escribe lo observado: \u00abLas primeras [n] fuentes acumularon [p]% de los documentos con fuente identificada; las zonas de Bradford necesitaron [a], [b] y [c] fuentes\u00bb. Evita \u00abse confirm\u00f3 la ley de Bradford\u00bb: la aplicaci\u00f3n describe el ajuste con un criterio declarado, no la contrasta."),
  subgraphs = list(reading = "Un subgrafo permite hacer una pregunta local: con qui\u00e9n colabora una autora, qu\u00e9 integra una comunidad o qu\u00e9 conecta una selecci\u00f3n. La extracci\u00f3n conserva todas las conexiones existentes entre los nodos elegidos. Al cambiar el universo, cambian denominadores y centralidades: una persona poco central en la red completa puede ocupar el centro de su equipo. Comprueba la red de origen antes de extender esa conclusi\u00f3n a todo el corpus.",
    reporting = "Documenta el criterio de selecci\u00f3n y distingue valores recalculados de los originales. \u00abSe examin\u00f3 el subgrafo inducido por [criterio], con [n] nodos y [m] conexiones\u00bb. Conserva la selecci\u00f3n y la red de origen para reproducir la extracci\u00f3n."),
  temporal = list(reading = "Lee juntas cantidad y proporci\u00f3n. Veinte documentos pueden ser m\u00e1s que diez y, a la vez, representar una parte menor si el corpus anual creci\u00f3 mucho. Una spline resume la proporci\u00f3n con suavidad cuando la cobertura permite ajustarla. Sus bandas no incluyen todos los errores posibles del estudio. Si faltan a\u00f1os o hay pocas observaciones, los puntos y sus denominadores ofrecen una lectura m\u00e1s defendible que una curva forzada.",
    reporting = "Indica que los grupos son fijos y que las proporciones incluyen documentos sin asignar en el denominador. Si presentas una spline, documenta el ajuste y sus diagn\u00f3sticos. Habla de evoluci\u00f3n anual observada; la estacionalidad necesita fechas m\u00e1s finas y varios ciclos."),
  topic_labels = list(reading = "Nombrar un tema consiste en contrastar una interpretaci\u00f3n con evidencia. Lee palabras principales, varios documentos representativos y alg\u00fan caso ambiguo. Escribe una definici\u00f3n corta y prueba si incluye esos textos sin ocultar diferencias importantes. Si otra persona propone un nombre distinto, esa discrepancia ayuda a revisar la etiqueta. Una IA puede sugerir alternativas, pero no conoce una categor\u00eda verdadera que el modelo haya descubierto.",
    reporting = "Conserva etiqueta, definici\u00f3n, documentos de apoyo y casos que la cuestionan. Explica qui\u00e9n revis\u00f3 los nombres y c\u00f3mo se resolvieron discrepancias. Una etiqueta transparente facilita que el lector eval\u00fae la interpretaci\u00f3n."),
  lda_time = list(reading = "El tema conserva su definici\u00f3n en toda la ejecuci\u00f3n; lo que cambia por a\u00f1o es cu\u00e1nto participa en los documentos. Si su media aumenta, puedes describir mayor presencia de esa mezcla tem\u00e1tica entre los registros fechados. No has demostrado que las probabilidades internas del tema evolucionaran. Un modelo din\u00e1mico plantea otra pregunta y necesita otro ajuste; esta vista no lo sustituye.",
    reporting = "Puedes escribir: \u00abSe describi\u00f3 la prevalencia anual de temas estimados sobre el corpus completo\u00bb. Informa a\u00f1os y documentos disponibles. Evita denominarlo LDA din\u00e1mico o convertir una media de mezclas en un recuento de art\u00edculos exclusivos de ese tema."),
  skills = list(reading = "Usa las skills como un protocolo de trabajo del investigador: primero localizar evidencia, despu\u00e9s formular afirmaciones, contrastarlas y revisar la redacci\u00f3n. La revisi\u00f3n benevolente ayuda a clarificar; la cr\u00edtica adversarial busca objeciones y alternativas. Ninguno de esos roles valida por s\u00ed mismo un resultado. T\u00fa decides qu\u00e9 objeci\u00f3n tiene fundamento y compruebas cada correcci\u00f3n.",
    reporting = "La autor\u00eda es siempre humana. Supervisa exhaustivamente cualquier texto asistido, verifica referencias en sus fuentes y cifras en los archivos completos. Declara la asistencia realmente utilizada y conserva el registro de comprobaciones. Estas instrucciones no prometen un art\u00edculo de alta calidad sin trabajo cient\u00edfico ni garantizan aceptaci\u00f3n editorial."),
  parallel = list(reading = "Para muchos res\u00famenes, varias tareas independientes pueden repartirse entre procesos de R. Un corpus peque\u00f1o suele tardar m\u00e1s si primero hay que abrir esos procesos y cargar modelos; por eso la aplicaci\u00f3n decide cu\u00e1ndo conviene repartir una etapa. La tabla muestra qu\u00e9 ocurri\u00f3 realmente, con trabajadores, lotes y tiempo. Si no se puede abrir el grupo de procesos, se reintenta secuencialmente y queda registrado.",
    reporting = "Paralelizar acelera ciertas etapas, pero no cambia sus reglas ni la selecci\u00f3n de documentos. Puedes informar el n\u00famero de trabajadores y versiones si necesitas documentar recursos. Compara resultados, no solo tiempos: el orden y la asignaci\u00f3n de cada documento deben permanecer iguales.")
)

# Contenido nuevo de V4: lo que cambia en el metodo y como decidir con apoyo.
v4_additions <- function() list(
  lda = list(
    action = c("Prior alpha (cambio de V4). La mezcla de temas de cada documento tiene un prior que controla cuanto puede concentrarse en pocos temas. V4 usa alpha = 1/k por defecto; el valor 50/k de topicmodels hace que, en textos cortos, las proporciones dependan sobre todo del prior. En los datos de pr\u00e1ctica (res\u00famenes de unas veinte palabras y cuatro temas) la proporci\u00f3n media del tema dominante fue 0,36 con 50/k y 0,93 con 1/k. Puedes cambiarlo en Opciones avanzadas; informa siempre el valor utilizado.",
      "Elegir k. Usa Elegir el n\u00famero de temas con apoyo: ajusta varias soluciones con varias semillas y las compara por coherencia, diversidad, estabilidad y perplejidad. Los criterios pueden discrepar; el valor de compromiso es solo un punto de partida. Despu\u00e9s lee los temas de dos o tres candidatos."),
    study = c("Calidad del modelo. Coherencia NPMI y UMass miden si las palabras principales de un tema co-ocurren en los mismos documentos (Mimno et al., 2011; R\u00f6der et al., 2015); aqu\u00ed se calculan con los propios documentos, as\u00ed que orientan pero no sustituyen a una evaluaci\u00f3n humana. La diversidad es la proporci\u00f3n de palabras principales distintas entre temas.",
      "Convergencia. Se guardan los estados del muestreador tras el burn-in y se devuelve el de mayor log-verosimilitud. El cambio relativo entre la primera y la segunda mitad de la traza es un indicador heur\u00edstico: si es grande, aumenta las iteraciones. No es una prueba formal de convergencia.")),
  jsd = list(
    action = c("Ruido de muestreo. La JSD calculada con conteos finitos es sesgada al alza: dos grupos del mismo corpus ya presentan JSD positiva. En la exportaci\u00f3n de ejemplo de 980 res\u00famenes, dos mitades aleatorias dieron una JSD media de 0,015 bits y dos grupos aleatorios de 20 documentos, de 0,27 bits. Por eso V4 compara la JSD observada con la que resulta al reasignar al azar los documentos entre A y B (permutaci\u00f3n), y muestra el exceso, el valor p y un intervalo bootstrap.",
      "Un valor p peque\u00f1o indica que la diferencia l\u00e9xica supera lo esperable por reasignaci\u00f3n de documentos; no prueba cambio conceptual ni causalidad, y supone intercambiabilidad de documentos (publicaciones de una misma revista o autor pueden no serlo)."),
    study = c("La permutaci\u00f3n mantiene los tama\u00f1os de A y B y reparte los documentos del conjunto A \u222a B al azar; el valor p es (1 + n\u00famero de JSD nulas \u2265 observada) / (B + 1). El intervalo bootstrap remuestrea documentos dentro de cada grupo y hereda el sesgo del estimador; usa el exceso sobre la nula como referencia principal.")),
  density = list(
    action = c("Estabilidad. Una sola ejecuci\u00f3n de UMAP + HDBSCAN no demuestra que los grupos sean reproducibles. En la exportaci\u00f3n de ejemplo de 980 res\u00famenes, cinco semillas con minPts = 10 dieron un ARI entre 0,51 y 0,65 respecto a la referencia: acuerdo bajo a moderado. Usa Evaluar estabilidad y sensibilidad y conf\u00eda sobre todo en los grupos que persisten entre semillas."),
    study = c("El ARI (Hubert y Arabie, 1985) compara dos agrupaciones del mismo conjunto de documentos: 1 es acuerdo total y 0 el esperable al azar. La persistencia de cada grupo es el mayor Jaccard con un grupo de otra semilla (Hennig, 2007). Las bandas de ARI citadas son una convenci\u00f3n orientativa (Steinley, 2004).")),
  ca = list(
    study = c("L\u00ednea base. Para cada eje se compara su porcentaje de inercia con el percentil 95 obtenido al permutar, columna a columna, las unidades en que aparece cada t\u00e9rmino. Un eje que no lo supera no se distingue de un reparto al azar con los mismos totales por t\u00e9rmino; los ejes 3 y siguientes no se interpretan como estructura salvo que la superen.")),
  pca = list(
    study = c("L\u00ednea base. Cada t\u00e9rmino se permuta de forma independiente entre documentos y se calcula el porcentaje de varianza por componente; el percentil 95 de esa distribuci\u00f3n es el umbral. Un componente por debajo no se distingue de la varianza esperable con t\u00e9rminos independientes.")),
  explore = list(
    action = c("Variantes de escritura. V4 unifica, al contar autores, palabras clave y fuentes, las variantes que solo difieren en may\u00fasculas, acentos o puntuaci\u00f3n (Machine Learning y machine learning; Smith, J. y Smith, J). No resuelve hom\u00f3nimos ni abreviaturas de revistas. La tabla de variantes unificadas permite revisar lo fusionado; puedes desactivarlo en Preparaci\u00f3n."))
)

enrich_lesson <- function(key, lesson) {
  s <- study_catalog()[[key]]
  add <- v4_additions()[[key]]
  if (!is.null(add) && !is.null(lesson)) {
    lesson$action <- c(lesson$action, add$action)
    if (length(add$study)) lesson$study <- c(lesson$study, add$study)
  }
  if(is.null(s)) return(lesson)
  lesson$reading <- s$reading; lesson$reporting <- s$reporting
  if(key == "load") {
    lesson$action <- c("Selecciona CSV, TSV, XLS o XLSX. En Excel se abre la primera hoja y puedes elegir otra; separador y codificaci\u00f3n solo se aplican a archivos de texto. Comprueba que la primera fila de datos contiene los nombres de las columnas. Los encabezados repetidos o vac\u00edos de Excel reciben nombres \u00fanicos y quedan registrados, sin borrar columnas.", lesson$action)
  }
  if(key == "jsd") {
    lesson$example <- c(lesson$example,
      "Ahora imagina que en A cl\u00ednica ocupa el 8% del vocabulario. B re\u00fane 99 textos de 100 tokens, cada uno con una menci\u00f3n (1%), y una revisi\u00f3n de 10.000 tokens con 2.000 menciones (20%). Al agrupar tokens, cl\u00ednica ocupa 2.099 de 19.900: 10,55%, por encima de A. Al dar el mismo peso a cada documento, su proporci\u00f3n media es (99 \u00d7 1% + 20%)/100: 1,19%, por debajo de A. La barra cambia de direcci\u00f3n porque has cambiado la pregunta, no porque una de las cuentas sea incorrecta. Su longitud exacta depende tambi\u00e9n del resto del vocabulario.")
    lesson$action <- c("Si buscas el reparto del conjunto de palabras, elige Tokens agrupados: los textos largos aportan m\u00e1s. Si buscas el perfil medio de los documentos, elige Documentos equilibrados: cada documento con vocabulario aporta el mismo peso. Para res\u00famenes de longitudes desiguales, la segunda opci\u00f3n suele ser un punto de partida razonable para comparar publicaciones; contrasta ambas si la longitud puede cambiar tu lectura. Ninguna garantiza una verdad conceptual ni equivale a contar qu\u00e9 piensa la mayor\u00eda de autores.",lesson$action[2])
    lesson$worked <- data.frame("Ponderaci\u00f3n"=c("Tokens agrupados","Documentos equilibrados"),"Cl\u00ednica en A"=c("8%","8%"),"Cl\u00ednica en B"=c("10,55%","1,19%"),"Direcci\u00f3n de la barra"=c("Hacia B","Hacia A"),"Pregunta que responde"=c("Reparto de todas las apariciones","Promedio de los repartos por documento"),check.names=FALSE)
  }
  lesson
}
